def src(n,title,author,url,date,kind,locator,passage,note='',status='Passage inspected',origin=None):
    sid=f'S{n:03d}'
    sources.append({'Source ID':sid,'Title':title,'Author / institution':author,'URL':url,'Publication date':date,'Access date':ASOF,'Source class':kind,'Primary / secondary':'Primary' if kind in ['Official record','Court order','Party publication','Statute'] else 'Secondary','Access status':status,'Origin ID':origin or sid,'Locator':locator,'Reliability / limitation':note or 'Supports only the inspected passage; attribution and time limits apply.','Language / geography':'English / India'})
    retrievals.append({'id':f'R{n:03d}','source_id':sid,'url_or_query':url,'access_date':ASOF,'route':'Web search and page retrieval','access_status':status,'origin_id':origin or sid,'locator':locator,'passage_paraphrase':passage,'method':'web.run passage inspection','result':status,'next_action':'Reuse historical passage; refresh dated legal and office status.'})
