S={s['Source ID']:s for s in sources}; R={r['source_id']:r for r in retrievals}
def table(name,lead,dates=()): tables[name]={'lead_columns':lead,'date_columns':list(dates),'rows':[]}
def add(name,rid,fields,nums,typ='Recorded fact',status='Supported',phase=None,note='',checked=None):
    fields={k:re.sub(r'(?<=[A-Za-z])(?=\d)|(?<=\d)(?=[A-Za-z])', ' ', v) if isinstance(v,str) and k not in ['Career phase','Context IDs'] else v for k,v in fields.items()}
    ids=[f'S{n:03d}' for n in nums]
    idcol={'Overview':'Overview ID','Context & Constraints':'Context ID','Career Timeline':'Timeline ID','Elections':'Election ID','Offices & Party':'Position ID','Controversies':'Matter ID','Legacy & Assessments':'Assessment ID'}.get(name,'Record ID')
    row={idcol:rid,**fields,'Claim type':typ,'Source IDs':'; '.join(ids)}
    if phase: row['Career phase']=phase
    if note: row['Research note']=note
    row['Corroboration']='Unresolved' if status=='Not reviewed' else 'Primary record' if any(S[i]['Source class'] in ['Official record','Statute','Court order'] for i in ids) else 'Interested source only' if ids and all(S[i]['Source class']=='Party publication' for i in ids) else 'Multiple sources / field-specific support' if len(ids)>1 else 'Single source'
    tables[name]['rows'].append(row)
    if typ=='Method / scope': return row
    if checked is None: checked=[k for k in fields if k in ['Finding / value','Finding','Description','Assessment']]
    for field in checked:
        val=row[field];cid=f'C-{rid}-{len([c for c in claims if c["record_id"]==rid])+1:02d}';ev=[]
        actual=status
        available=[i for i in ids if R[i]['access_status']=='Passage inspected']
        if not available: actual='Not reviewed'
        if actual in ['Supported','Partially supported','Disputed']:
            for sid in available:
                eid=f'EV{len(evidence)+1:04d}'; ev.append(eid)
                evidence.append({'id':eid,'claim_id':cid,'source_id':sid,'retrieval_id':R[sid]['id'],'locator':R[sid]['locator'],'passage_paraphrase':R[sid]['passage_paraphrase'],'relation':'Supports','reviewed_by':'Codex passage review','reviewed_at':ASOF,'note':'Combined sources support bounded field wording; synthesis is labelled Analysis.'})
        claims.append({'id':cid,'sheet':name,'record_id':rid,'field':field,'statement':val,'fingerprint':hashlib.sha256(json.dumps(val,ensure_ascii=False,sort_keys=True).encode()).hexdigest(),'claim_type':typ,'status':actual,'priority':'High' if name in ['Elections','Controversies'] else 'Normal','candidate_source_ids':ids,'evidence_ids':ev,'contradictions':[],'review_note':note or 'Field checked against inspected passage; source-specific limitations retained.'})
    return row
P1='P1 | Entry and opposition, 1997–2004';P2='P2 | UPA influence, 2004–2014';P3='P3 | Defeat and succession, 2014–2022';P4='P4 | Senior parliamentary role, 2022–2026';phases=[P1,P2,P3,P4]
table('Overview',['Overview ID','Topic','Finding / value'])
table('Context & Constraints',['Context ID','Career phase','Coverage item','Finding'])
table('Career Timeline',['Timeline ID','Period','Event','Description'],['Exact date'])
table('Elections',['Election ID','Year','Constituency','Result','Candidate votes','Signed vote margin'])
table('Offices & Party',['Position ID','Position / institution','Period','Finding'],['Start date','End date'])
table('Policy & Governance',['Record ID','Initiative / decision','Finding','Stage'])
table('Ideas & Political Method',['Record ID','Topic','Finding'])
table('Controversies',['Matter ID','Matter','Finding','Procedural status'],['Latest evidence date'])
table('Legacy & Assessments',['Assessment ID','Theme','Assessment'])
def ov(n,topic,finding,ids,typ='Recorded fact',**kw): return add('Overview',f'OV{n:02d}',{'Topic':topic,'Finding / value':finding},ids,typ,**kw)
